'use strict';
(() => {
  const esc=escapeHTML;
  let data=null, local=null, selected=null, facts=new Map(), drafted=[];
  const modeNames={current_review:'현재 자료 재검토',historical_public:'당시 공개 정보',observed_live:'시스템 관측 기준'};
  const stageNames={extract:'추출·원문 위치·개발 참조',compare:'이전 정보·변화·공식',review:'검토 사유 연결',cards:'통합 카드',feedback_snapshot:'파일 검토 이력',validate:'카드 계약 검증'};
  const statuses={succeeded:'완료',reused:'검증 후 재사용',failed:'실패',retryable:'재시도 가능',skipped:'미실행',computed:'계산됨',withheld:'계산 보류',insufficient_inputs:'입력 부족',not_comparable:'비교 불가',needs_review:'사람 검토 필요',candidate:'검토 후보',conflict_candidate:'충돌 후보',executed_development:'개발 실행',not_evaluated:'미평가'};
  const titles={S0:'S0 · 시간순 최소 사실',S1:'S1 · 규칙 검토 목록',S3:'S3 · 통합 카드',S2:'S2 · 학습 모델',S4:'S4 · 선택 LLM',S5:'S5 · 전체 LLM'};
  const reasonNames={definition_version_mismatch:'발표별 사업부 표시 정의가 다름',actual_relation_validity_unknown:'보고 관계 유효기간 미확인',scope_unresolved_at_cutoff:'당시 사업 범위 근거 미확인',current_only_dependency:'사후 문맥을 과거에 사용할 수 없음',query_unavailable:'당시 새 항목의 문맥 부족',all_candidates_incompatible:'이전 후보 비교 조건 불일치',all_candidates_time_excluded:'이전 후보가 시점 검사에서 제외됨',no_hit_in_limited_corpus:'제한 자료 안에 이전 후보 없음',prior_not_available:'이전 값 미확인',same_day_order_unknown:'같은 날 공개 순서 미확인',future_information:'기준 시점 이후 자료'};
  const reason=code=>reasonNames[code]||code;
  const label=f=>metrics[f.normalized.metric_id]||'사업부 보고 관계';
  const value=f=>f.kind==='business_relation'?'Microsoft → '+(scopes[f.normalized.scope_id]||f.normalized.scope_id):exact(f.normalized.numeric_value)+' '+(f.normalized.currency||'');
  const date=f=>f.period.as_of_date||[f.period.period_start,f.period.period_end].filter(Boolean).join(' ~ ');
  const stats=items=>items.map(([name,note,n,unit])=>`<article class="stat-card"><span class="stat-label">${esc(name)}</span><div class="stat-number">${esc(n)}<small>${esc(unit||'')}</small></div><div class="stat-foot">${esc(note)}</div></article>`).join('');
  const seconds=n=>n==null?'미측정':Number(n).toFixed(6)+'초';
  const source=(f,heading)=>!f?`<p>${esc(heading)}: 이전 정보 미확인</p>`:`<section class="comparison-source"><h3>${esc(heading)} · ${esc(label(f))}</h3><strong>${esc(value(f))}</strong><p>${esc(scopes[f.normalized.scope_id]||f.normalized.scope_id)}<br>대상: ${esc(date(f))}<br>발표 날짜: ${esc(f.published_date)} · 정확 시각 미확인<br>관측: ${esc(f.observed_at)}<br>표시 정의: ${esc(f.normalized.definition_version)}</p><a class="source-link" href="${esc(f.source_url)}" target="_blank" rel="noopener noreferrer">공식 발표 열기</a><details><summary>원문 위치·문서·revision</summary><p class="run-meta">${esc(f.doc_id)}<br>${esc(f.revision_id)}</p>${f.evidence.map(e=>`<p class="xpath">${esc(e.kind)} · ${esc(e.location)}<br>Unicode code point [${e.start}, ${e.end})</p>`).join('')}</details></section>`;
  function options(id,values,fn){$(id).innerHTML='<option value="all">전체</option>'+[...new Set(values)].sort().map(v=>`<option value="${esc(v)}">${esc(fn(v))}</option>`).join('');}
  function draftKey(){return 'research-p08-drafts:'+data.P08.run_id;}
  function readDrafts(){try{drafted=JSON.parse(localStorage.getItem(draftKey())||'[]');if(!Array.isArray(drafted))drafted=[];}catch{drafted=[];}}
  function saveDrafts(){try{localStorage.setItem(draftKey(),JSON.stringify(drafted));}catch{notice('이 기기의 저장 공간을 사용할 수 없습니다. 파일로 내보내세요.',true);}history();}
  function renderCards(){
    if(!data)return;
    const s=data.P08.summary;
    $('card-summary').innerHTML=stats([['검토 카드','숫자와 공유 근거 관계를 묶음',s.cards,'개'],['입력 후보','숫자 '+s.numeric_candidates+' · 관계 '+s.relation_candidates,s.candidates,'개'],['실제 입력','Microsoft 1개 기업',s.documents,'발표'],['사람 gold','독립 test도 0개',s.human_gold,'개']]);
    const cards=data.P08.cards.filter(c=>{const f=c.facts[0];return ($('card-date').value==='all'||f.published_date===$('card-date').value)&&($('card-scope').value==='all'||f.normalized.scope_id===$('card-scope').value)&&($('card-metric').value==='all'||f.normalized.metric_id===$('card-metric').value);});
    $('card-count').textContent=cards.length;
    if(!cards.some(c=>c.card_id===selected))selected=cards[0]?.card_id;
    $('card-list').innerHTML=cards.length?cards.map(c=>{const f=c.facts[0];return `<tr class="result-row ${c.card_id===selected?'selected-row':''}"><td class="record-main"><button class="record-button" data-card="${esc(c.card_id)}"><strong>${esc(label(f))}</strong><small>${esc(f.published_date)} · ${esc(scopes[f.normalized.scope_id]||f.normalized.scope_id)}</small></button></td><td>${esc(date(f))}</td><td>검토 필요${c.business_relation_refs.length?' · 공유 근거 관계':''}</td></tr>`;}).join(''):'<tr><td colspan="3" class="empty">조건에 맞는 카드가 없습니다.</td></tr>';
    $('card-list').querySelectorAll('[data-card]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.card;renderCards();}));
    const c=cards.find(c=>c.card_id===selected);if(!c){$('card-detail').textContent='필터를 바꾸면 카드가 표시됩니다.';return;}
    const mode=$('card-mode').value;const changes=c.changes.filter(x=>x.cutoff_mode===mode);const calcs=c.calculations.filter(x=>x.cutoff_mode===mode);
    $('card-detail').innerHTML=`<div class="phase-details"><span class="eyebrow">기업 발표 주장 · 사람 검토 필요</span><h2>${esc(label(c.facts[0]))}</h2>${c.facts.map(f=>source(f,'새 발표')).join('')}<section class="detail-section"><h3>이전 정보와 변화 · ${esc(modeNames[mode])}</h3>${changes.map(x=>`<details ${x.status==='computed'?'open':''}><summary>${esc(statuses[x.status]||x.status)} · ${esc(x.comparison_basis)}</summary>${source(facts.get(x.prior_record_id),'이전/비교 정보')}<p>기준: ${esc(x.cutoff)}<br>이전 값: ${esc(exact(x.old_value))}<br>새 값: ${esc(exact(x.new_value))}<br>변화량: ${esc(exact(x.delta))}<br>상대 변화(비율): ${esc(exact(x.relative_delta))}<br>공식: ${esc(x.formula_id||'미실행')}</p><p>${esc(x.reasons.map(reason).join(' · ')||'비교 조건 검사됨; 사람 검토 필요')}</p><details><summary>비교 조건</summary><pre>${esc(JSON.stringify(x.compatibility,null,2))}</pre></details></details>`).join('')||'<p>이전 정보 결과 없음</p>'}</section><section class="detail-section"><h3>가능한 계산과 입력</h3>${calcs.map(x=>`<details><summary>${esc(x.formula_id)} · ${esc(statuses[x.status]||x.status)}</summary><p>${esc(x.definition)}<br>결과: ${esc(exact(x.output))} ${esc(x.output_unit||'')}<br>${esc(x.reasons.concat(x.missing_inputs).map(reason).join(' · '))}<br>반올림: ${esc(x.rounding)}</p>${x.input_refs.map(i=>source(facts.get(i),'공식 입력')).join('')}</details>`).join('')||'<p>이 항목의 공식 계산은 해당 없음</p>'}</section><section class="detail-section"><h3>추가 확인 질문</h3><ul class="reason-list">${c.review_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><p>중요성 점수·확률 미평가 · 순이익→CFO 대사 미완료</p></section><section class="detail-section"><h3>이 기기의 검토 초안</h3><p>공유 결과에 자동 저장되지 않습니다. 작성자·시각은 자체 신고입니다.</p><form id="feedback-form"><label>작성자 별칭<input id="draft-actor" value="reviewer-a" maxlength="100" pattern="[A-Za-z0-9_.:-]+" required></label><label>행동<select id="draft-action"><option value="confirm">확인</option><option value="correct_fact">사실 수정</option><option value="irrelevant">무관</option><option value="investigate">추가조사</option><option value="update_assumption">가정 수정</option></select></label><label>필드<select id="draft-field"></select></label><label id="draft-after-label">수정 값<input id="draft-after"></label><p id="draft-before"></p><button class="primary" type="submit">이 기기 초안에 추가</button></form><p id="draft-result" role="status"></p></section><details><summary>후보·카드 버전 연결</summary><p class="run-meta">${esc(c.card_id)}<br>${esc(c.card_version)}<br>${esc(c.candidate_refs.join(' · '))}<br>pipeline ${esc(c.pipeline_status)} · evidence ${esc(c.evidence_status)}</p></details></div>`;
    const actionFields={confirm:['review_status'],correct_fact:['numeric_value','scope_id','reference_period'],irrelevant:['review_status'],investigate:['review_status'],update_assumption:['assumption_status']};
    const base=f=>({review_status:'needs_review',numeric_value:c.facts[0].normalized.numeric_value,scope_id:c.facts[0].normalized.scope_id,reference_period:c.facts[0].period,assumption_status:null})[f];
    function formFields(){const a=$('draft-action').value;$('draft-field').innerHTML=actionFields[a].map(f=>`<option value="${f}">${esc(({review_status:'검토 상태',numeric_value:'숫자',scope_id:'사업 범위',reference_period:'대상 기간(JSON)',assumption_status:'가정 상태'})[f])}</option>`).join('');formValue();}
    function formValue(){const a=$('draft-action').value,f=$('draft-field').value;$('draft-after-label').hidden=['confirm','irrelevant','investigate'].includes(a);$('draft-after').value=f==='reference_period'?JSON.stringify(c.facts[0].period):f==='assumption_status'?'proposed':'';$('draft-before').textContent='원래 값: '+JSON.stringify(base(f));}
    $('draft-action').addEventListener('change',formFields);$('draft-field').addEventListener('change',formValue);formFields();
    $('feedback-form').addEventListener('submit',e=>{e.preventDefault();try{
      const action=$('draft-action').value,field=$('draft-field').value;let after=({confirm:'confirmed_candidate',irrelevant:'irrelevant_candidate',investigate:'investigate_candidate'})[action]||$('draft-after').value;
      if(field==='reference_period')after=JSON.parse(after);
      if(field==='numeric_value'&&!/^-?\d{1,30}(\.\d{1,28})?$/.test(after))throw new Error('숫자는 배율을 추가하지 않은 Decimal 문자열로 입력하세요.');
      const actor=$('draft-actor').value;if(!/^[A-Za-z0-9_.:-]{1,100}$/.test(actor))throw new Error('별칭은 영문·숫자·_.:-로 입력하세요.');
      const id=crypto.randomUUID();drafted.push({feedback_id:'F-'+id,idempotency_key:'I-'+id,source_run:data.P08.run_id,card_id:c.card_id,card_version:c.card_version,actor_id:actor,action,field,before:base(field),after,evidence_refs:c.facts.flatMap(f=>f.evidence.map(x=>x.evidence_id)),reason_code:({confirm:'source_checked',correct_fact:'value_mismatch',irrelevant:'not_relevant',investigate:'needs_more_evidence',update_assumption:'assumption_changed'})[action],created_at:new Date().toISOString()});saveDrafts();$('draft-result').textContent='이 기기의 초안에 추가했습니다. 파일로 내보내세요.';
    }catch(err){$('draft-result').textContent=err.message;}});
  }
  function history(){
    if(!data)return;const f=data.P08.feedback;
    $('feedback-state').textContent=`이 기기의 초안 ${drafted.length}건 · 공유 snapshot 반영 ${f.events.length}건 · 검토 revision ${f.revision} · 충돌 ${f.conflicts.length}건`;
    $('feedback-history').innerHTML=f.events.length?f.events.map(e=>`<details><summary>${esc(e.action)} · ${esc(statuses[e.review_status]||e.review_status)}</summary><p>${esc(e.card_id)} · ${esc(e.field)}<br>원래 값 ${esc(JSON.stringify(e.before))} → 검토 제안 ${esc(JSON.stringify(e.after))}<br>작성 ${esc(e.created_at)} · 수신 ${esc(e.received_at)}<br>작성자 자체 신고 · 학습 제외 · gold 아님</p></details>`).join(''):'<p>공유 결과에 반영된 사람 검토 기록이 없습니다.</p>';
    if(f.conflicts.length)$('feedback-history').insertAdjacentHTML('beforeend',`<p>충돌은 원래 후보를 덮어쓰지 않습니다. 같은 카드 버전의 반복 실행 이력도 연결합니다.</p>${f.conflicts.map(c=>{const r=f.resolutions.filter(r=>r.conflict_id===c.conflict_id).at(-1);return `<p>${esc(c.conflict_id)} · ${esc(c.field)} · ${esc(r?({adopt:'채택 이력 있음',merge:'병합 이력 있음',defer:'검토 보류'})[r.decision]:'미해결')}</p>`;}).join('')}`);
    if(f.resolutions.length)$('feedback-history').insertAdjacentHTML('beforeend',f.resolutions.map(r=>`<p>해결 이력 ${esc(r.conflict_id)} · ${esc(r.decision)} · ${esc(r.created_at)}</p>`).join(''));
  }
  function renderPipeline(){if(!data)return;const p=data.P08.pipeline;const f=data.P08.feedback;$('pipeline-summary').innerHTML=stats([['실행 단계','추출부터 카드 검증까지',p.stages.length,'단계'],['검토 기록','공유 snapshot에 반영',f.events.length,'건'],['충돌 기록','자동 덮어쓰기 없음',f.conflicts.length,'건'],['외부 호출','신규 원문 수집도 0건',p.external_calls,'회']]);$('pipeline-list').innerHTML=p.stages.map(s=>`<tr><td>${esc(stageNames[s.stage]||s.stage)}</td><td>${esc(statuses[s.status]||s.status)}</td><td>${s.counts?esc(`${s.counts.unit}: ${s.counts.input} / ${s.counts.normal} / ${s.counts.failed} / ${s.counts.held}`):esc(s.reason||'미실행')}</td><td>${esc(seconds(s.elapsed_seconds))}</td></tr>`).join('');history();}
  function renderEvaluation(){
    if(!data)return;const e=data.P09;if(!e){$('evaluation-context').textContent='P09 결과 미게시';return;}
    $('evaluation-summary').innerHTML=stats([['공학 검사','정확도 점수가 아닙니다.',e.engineering_checks_passed+'/'+e.engineering_checks_total,''],['합성·장애 검사','실제 기사/사건 분모와 별도',e.synthetic_passed+'/'+e.synthetic_total,''],['독립 test','사람 gold·qrels 0개',e.summary.independent_test,'개'],['실제 사람 세션','사용성·시간절감 미측정',e.summary.actual_participants,'명']]);
    $('evaluation-context').textContent=`Microsoft ${e.summary.documents}문서 · ${e.summary.families} family · 같은 노출 그룹 · ${e.summary.candidates} 후보 · ${e.summary.cards} 카드 · 검토 예산 39 후보. 평가 source P08 ${e.source_p08_run}.`;
    $('evaluation-systems').innerHTML=e.systems.map(s=>`<tr><td>${esc(titles[s.system])}</td><td>${esc(statuses[s.status]||s.status)}</td><td>${esc(s.unit==='card'?'카드':s.unit==='candidate'?'후보':'해당 없음')} / ${esc(s.records??'미실행')}</td><td>${esc(s.covered_candidates??'미실행')}</td><td>${esc(seconds(s.materialization_seconds))} / ${esc(seconds(s.warm_seconds))}</td></tr>`).join('');
    $('evaluation-checks').innerHTML=`<p>같은 agent 별도 실행 의미 결과 ${e.semantic_reproduction?'일치':'불일치'}. P04/P05 동결 package 보존 검사 포함. 팀원 재실행은 미실행.</p><p>실제 배치 단계 wall 합계 ${esc(seconds(e.stage_wall_seconds))} · 외부 호출 ${e.external_calls}회. 운영 비용·1000문서 환산·메모리 peak는 미측정.</p><p>현재 자료 재검토 변화 ${e.mode_counts.current_review.computed}/${e.mode_counts.current_review.attempts}, 당시 공개 ${e.mode_counts.historical_public.computed}/${e.mode_counts.historical_public.attempts}, 관측 기준 ${e.mode_counts.observed_live.computed}/${e.mode_counts.observed_live.attempts}. 동일 발표 비교열을 독립 prior 검색으로 세지 않습니다.</p><p>공식 계산: 현재 ${e.mode_counts.current_review.calculated}/${e.mode_counts.current_review.calculation_attempts} · 당시 ${e.mode_counts.historical_public.calculated}/${e.mode_counts.historical_public.calculation_attempts} · 관측 ${e.mode_counts.observed_live.calculated}/${e.mode_counts.observed_live.calculation_attempts}. 계산됨도 사람 검토 필요입니다.</p><p>정확/희소 검색 ${e.retrieval_queries} query · 짝지은 ${e.paired_query_groups} query 그룹. 선택 일치 ${e.exact_sparse_selection_agreement}/${e.paired_query_groups}는 개발 동작 비교이며 Recall이 아닙니다.</p>`;
    const cases=e.failure_cases.filter(x=>$('failure-stage').value==='all'||x.stage===$('failure-stage').value);
    $('evaluation-failures').innerHTML=cases.map(x=>`<tr><td><details><summary>${esc(modeNames[x.cutoff_mode])} · ${esc(x.comparison_basis||'공식')}</summary><p>${esc(x.case_id)}<br>${esc(x.candidate_refs.join(' · '))}</p></details></td><td>${esc(statuses[x.status]||x.status)}</td><td>${esc(x.reasons.map(reason).join(' · '))}</td></tr>`).join('');
    $('evaluation-missing').innerHTML='<ul>'+e.independent_metrics.map(m=>`<li>${esc(({numeric_accuracy:'숫자 정확도',relation_accuracy:'관계 정확도',retrieval_recall_at_k:'검색 Recall',change_accuracy:'변화 정확도',important_recall:'중요 사건 Recall',ndcg:'검토 순위 효용',human_time_saved:'사람 검토시간 절감'})[m.metric]||m.metric)}: 미평가 · 평가 가능한 분모 ${m.denominator}</li>`).join('')+'</ul><p>정확한 발표 시각·날짜 충돌·사업부 정의·관계 유효기간·전체 본문 감사·CFO 대사 입력도 미확인입니다. 신뢰구간과 p-value는 미측정입니다.</p>';
  }
  window.renderIntegrationReports=view=>{if(!data)return;if(['cards','pipeline','evaluation'].includes(view)){$('version').textContent=view==='evaluation'?data.P09?.protocol_version||'미평가':data.P08.policy_version;$('run-label').textContent=`P08 ${data.P08.run_id} · P09 ${data.P09?.run_id||'미게시'}`;$('mode').textContent=local?.enabled?'내 PC · 파일 검토':'공유 게시 snapshot';}};
  async function loadIntegration(){const r=await fetch('/integration.json',{cache:'no-store'});if(!r.ok)throw new Error('통합 결과를 읽지 못했습니다.');data=await r.json();if(data.schema_version!=='p08-p09-site-0.1')throw new Error('통합 결과 형식을 확인하세요.');facts=new Map(data.P08.cards.flatMap(c=>c.facts.map(f=>[f.record_id,f])));readDrafts();options('card-date',data.P08.cards.map(c=>c.facts[0].published_date),v=>v);options('card-scope',data.P08.cards.map(c=>c.facts[0].normalized.scope_id),v=>scopes[v]||v);options('card-metric',data.P08.cards.map(c=>c.facts[0].normalized.metric_id),v=>metrics[v]||v);renderCards();renderPipeline();renderEvaluation();window.renderIntegrationReports(state.view);}
  for(const id of ['card-date','card-scope','card-metric','card-mode'])$(id).addEventListener('change',renderCards);
  $('failure-stage').addEventListener('change',renderEvaluation);
  $('feedback-export').addEventListener('click',()=>{if(!data)return;const blob=new Blob([JSON.stringify({schema_version:'p08-feedback-export-0.1',source_run:data.P08.run_id,events:drafted},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='p08-feedback-'+data.P08.run_id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('feedback-state').textContent=`초안 ${drafted.length}건을 파일로 내보냈습니다. 공유 반영은 소유자 가져오기·재게시 후 완료됩니다.`;});
  $('feedback-clear').addEventListener('click',()=>{drafted=[];saveDrafts();});
  $('feedback-import').addEventListener('change',async ev=>{const f=ev.target.files[0];if(!f||!local?.enabled)return;try{if(f.size>512000)throw new Error('512KB 이하의 파일을 사용하세요.');const payload=JSON.parse(await f.text());const r=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json','X-P05-Token':local.token},body:JSON.stringify(payload)});const body=await r.json();if(!r.ok)throw new Error(body.error);$('feedback-state').textContent=`로컬 수신 ${body.accepted} · 중복 ${body.duplicates} · 거부 ${body.rejected.length} · 충돌 ${body.conflicts}. 새 통합 실행 후 게시해야 공유됩니다.`;}catch(err){$('feedback-state').textContent=err.message;}ev.target.value='';});
  $('p08-run-button').addEventListener('click',async()=>{if(!local?.enabled){notice('저장소에서 python web/p05/server.py를 실행한 뒤 로컬 화면의 통합 실행 버튼을 사용하세요.');return;}const b=$('p08-run-button');b.disabled=true;try{const r=await fetch('/api/run-p08',{method:'POST',headers:{'X-P05-Token':local.token}});const body=await r.json();if(!r.ok)throw new Error(body.error);let job;do{await new Promise(resolve=>setTimeout(resolve,700));const s=await fetch('/api/p08-job',{cache:'no-store'});job=await s.json();$('p08-run-note').textContent='내 PC에서 고정 입력을 처리 중입니다.';}while(job.busy);if(job.error)throw new Error('실행 실패: '+job.error);await loadIntegration();$('p08-run-note').textContent='새 로컬 결과를 반영했습니다. 공유 사이트는 재게시 후 갱신됩니다. P09는 고정된 평가 source를 유지합니다.';}catch(err){$('p08-run-note').textContent=err.message;}finally{b.disabled=false;}});
  loadIntegration().catch(err=>notice(err.message,true));
  fetch('/api/p08-state',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error();return r.json();}).then(d=>{local=d;$('p08-run-button').textContent='내 PC 통합 실행';$('feedback-import').disabled=false;$('p08-run-note').textContent='추출 → 비교 → 검토 사유 → 카드 → 파일 이력 검증을 이 PC에서 실행합니다. 공유 사이트를 자동 갱신하지 않습니다.';window.renderIntegrationReports(state.view);}).catch(()=>{});
})();
